function subarraySum(nums) {
  const prefix = [0];
  for (const value of nums) {
    prefix.push(prefix[prefix.length - 1] + value);
  }

  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    const start = Math.max(0, i - nums[i]);
    total += prefix[i + 1] - prefix[start];
  }
  return total;
}

brute:
function subarraySum(nums) {
  // Walk back from each index, nums[i] steps at most, adding every element on the way.
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i, steps = 0; j >= 0 && steps <= nums[i]; j--, steps++) total += nums[j];
  }
  return total;
}

