function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 100 : 1 + pick(8);
  // Small values keep subarrays short; large ones reach back to index 0.
  const top = large ? [5, 50, 1000][pick(3)] : [1, 3, 1000][pick(3)];
  return [Array.from({ length: n }, () => 1 + pick(top))];
}
